package app.baki

import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The Kotlin port must reproduce the numbers the shipping web app produces for the same
 * data — golden.json was generated by asking index.html itself.
 */
class GoldenTest {

    private fun resource(name: String): String =
        GoldenTest::class.java.classLoader.getResourceAsStream(name)?.bufferedReader()?.readText()
            ?: error("missing test resource $name")

    private val store: Store by lazy { BakiJson.decodeFromString<Store>(resource("store.json")) }
    private val golden: Map<String, kotlinx.serialization.json.JsonElement> by lazy {
        BakiJson.parseToJsonElement(resource("golden.json")) as kotlinx.serialization.json.JsonObject
    }

    private fun near(a: Double, b: Double, eps: Double = 0.005): Boolean = abs(a - b) <= eps

    @Test
    fun parsesTheRealStore() {
        assertEquals(23, store.entries.size, "entries")
        assertEquals(4, store.shifts.size, "shifts")
        assertEquals(11.0, store.settings.profit.kmPerLitre, "km/L from settings")
        assertEquals(1, store.statements.size, "imported statements")
    }

    @Test
    fun everyShiftMatchesTheWebApp() {
        val rows = (golden["rows"] as kotlinx.serialization.json.JsonArray)
            .map { it as kotlinx.serialization.json.JsonObject }
        assertEquals(store.shifts.size, rows.size, "row count")
        for (row in rows) {
            val id = (row["id"] as kotlinx.serialization.json.JsonPrimitive).content
            val sh = store.shifts.first { it.id == id }
            val m = shiftMetrics(sh, store.settings.profit)
            fun want(k: String) = (row[k] as kotlinx.serialization.json.JsonPrimitive).content.toDouble()
            val label = "shift $id (${sh.date})"
            assertTrue(near(m.km, want("km")), "$label km: ${m.km} vs ${want("km")}")
            assertTrue(near(m.fuel, want("fuel")), "$label fuel: ${m.fuel} vs ${want("fuel")}")
            assertTrue(near(m.wear, want("wear")), "$label wear: ${m.wear} vs ${want("wear")}")
            assertTrue(near(m.net, want("net")), "$label net: ${m.net} vs ${want("net")}")
            assertTrue(near(m.gross, want("gross")), "$label gross: ${m.gross} vs ${want("gross")}")
            assertTrue(near(m.grabFee, want("grabFee")), "$label cover: ${m.grabFee} vs ${want("grabFee")}")
            val band = (row["band"] as kotlinx.serialization.json.JsonPrimitive).content
            assertEquals(band, m.band, "$label band")
            val wantHr = row["netHr"]?.let { (it as kotlinx.serialization.json.JsonPrimitive).content.toDoubleOrNull() }
            if (wantHr == null) assertTrue(m.netHr == null) else assertTrue(near(m.netHr!!, wantHr), "$label RM/hr")
        }
    }

    @Test
    fun totalsMatchTheWebApp() {
        val rows = store.shifts.map { shiftMetrics(it, store.settings.profit) }
        val net = rows.sumOf { it.net }
        val hrs = rows.sumOf { it.hrs }
        val wantNet = (golden["totalNet"] as kotlinx.serialization.json.JsonPrimitive).content.toDouble()
        val wantBlended = (golden["blended"] as kotlinx.serialization.json.JsonPrimitive).content.toDouble()
        assertTrue(near(net, wantNet), "total net: $net vs $wantNet")
        assertTrue(near(net / hrs, wantBlended), "blended: ${net / hrs} vs $wantBlended")
    }

    @Test
    fun mergeKeepsNewestAndHonoursTombstones() {
        val a = store.copy(entries = store.entries.take(10))
        val b = store.copy(entries = store.entries)
        val merged = mergeStores(a, b)
        assertEquals(store.entries.size, merged.entries.size, "union without tombstones")

        val victim = store.entries.first().id
        val clipped = mergeStores(a, b, dead = setOf(victim))
        assertTrue(clipped.entries.none { it.id == victim }, "tombstone removes the record")

        // a newer edit beats an older copy
        val stale = b.entries.map { if (it.id == victim) it.copy(note = "old", updated = "2000-01-01T00:00:00Z") else it }
        val fresh = b.entries.map { if (it.id == victim) it.copy(note = "new", updated = "2030-01-01T00:00:00Z") else it }
        val winner = mergeStores(b.copy(entries = stale), b.copy(entries = fresh)).entries.first { it.id == victim }
        assertEquals("new", winner.note)
    }
}
